    source: 'TechWeb / 游民星空 / 新浪数码',
    sourceUrl: 'https://www.techweb.com.cn/it/2026-04-28/2974848.shtml',
    summary: '苹果于4月27日宣布为App Store开发者推出全新订阅选项:带有12个月承诺期的月度订阅。用户需签订一年合约,但可按月付费,费用等同年度订阅优惠价,比按月单独付费节省20%-30%。用户可随时取消订阅,但需完成已承诺的12期付款。Apple账户中清晰显示已付期数和剩余期数,续订前发送邮件及推送通知提醒。开发者即日起可在App Store Connect中创建此类订阅并在Xcode中测试。该功能将于5月随iOS 26.5及对应版本更新面向用户上线,需运行iOS 26.4及以上版本。美国和新加坡市场暂不支持。',
