    id: '75',
    title: '欧盟委员会首次DMA审查:数字市场法实施两年保持适用性,产生积极影响',
    source: '欧盟委员会',
    sourceUrl: 'https://digital-markets-act.ec.europa.eu/review-highlights-digital-markets-act-remains-fit-purpose-and-has-positive-impact-2026-04-28_en',
    summary: '欧盟委员会发布《数字市场法》(DMA)首次审查报告,认为DMA在实施两年后仍然适用于目标且产生了积极影响。具体成就包括:用户可在切换服务时转移数据;可选择替代搜索引擎和浏览器;可自主决定是否允许守门人跨服务合并个人数据以防止未经授权的用户画像。在开放守门人生态系统方面DMA取得显著进展:可穿戴设备制造商(耳机、智能手表等)获得与守门人操作系统增强的互操作性;替代浏览器和搜索引擎越来越多被用户设为默认设备选项;第三方应用商店已在开放系统上启动;得益于互操作性义务,新的即时通讯应用已推出。这是欧盟对DMA实施效果的第一次正式全面评估,报告肯定了该法在重塑数字市场竞争格局方面的积极作用。',
    aiComment: {
      overallImpact: '欧盟委员会首次DMA审查报告具有里程碑意义。报告明确肯定了DMA在实施两年后"仍然适用且产生了积极影响",意味着欧盟将继续严格执行DMA并可能扩大监管范围。具体成就包括互操作性增强(可穿戴设备、第三方应用商店、即时通讯)、用户选择权提升(搜索引擎、浏览器、数据自主权)。这一结论为全球数字市场规制提供了重要参考——欧盟模式"先监管后观察"的策略被论证为有效。报告释放的信号是:DMA不会放松,反而可能延伸到云服务和AI领域(欧盟此前已提出将云服务纳入"守门人"定义)。对守门人企业(Apple、Google、Meta、Amazon等)而言,合规压力将进一步加大。',
      huaweiImpact: '欧盟首次DMA审查对华为构成战略利好与合规警示的双重信号。利好层面:DMA审查报告明确肯定了互操作性义务的成效——可穿戴设备厂商获得与守门人操作系统的增强互操作性、第三方应用商店已获准上线、即时通讯互操作催生了新应用。这些进展对华为具有直接商业价值:华为手表/手环等可穿戴设备在欧盟市场可获得与iOS/Android更深入的互操作能力;华为AppGallery作为第三方应用商店,可在DMA框架下争取在iOS设备上提供服务的法律和政策支持;华为畅连可参考WhatsApp互操作模式,与欧盟市场的主流即时通讯应用建立互联互通。战略层面:DMA审查报告显示欧盟在数字经济监管上的决心不减,华为应积极研究DMA合规要求,主动建立合规体系,避免因监管摩擦影响欧洲市场进展。同时,华为可将DMA创造的开放窗口转化为竞争优势,在第三方应用商店、可穿戴设备、即时通讯等赛道积极布局。',
    },
