    id: '95',
    title: '苹果请求美最高法院暂停Epic案执行,称禁令范围应仅限Epic而非全体开发者',
    source: 'IT之家 / 凤凰网科技 / 9to5Mac',
    sourceUrl: 'https://tech.ifeng.com/c/8ssAHvyK2xc',
    summary: '5月4日,苹果向美国最高法院提交申请,请求暂停执行第九巡回上诉法院关于Epic Games反垄断案的指令。此前4月28日,第九巡回上诉法院推翻了苹果在上诉期间维持现行App Store佣金收费模式的裁定,苹果必须回到下级法院重新商定对引导用户使用第三方支付渠道的开发者的佣金率。苹果核心论点是2021年禁令应仅适用于Epic Games而非全体开发者,藐视法庭的定性不应有。最高法院大法官卡根随后拒绝了苹果的紧急中止申请,使得第九巡回上诉法院的藐视法庭认定维持有效。',
    aiComment: {
      overallImpact: '苹果Epic反垄断案的最新回合标志着App Store商业模式面临前所未有的司法挑战。第九巡回上诉法院推翻苹果维持现行佣金的上诉裁定,意味着苹果必须重新协商对第三方支付引导开发者的佣金抽取方式——这不仅是Epic的胜利,更可能彻底改变全球iOS应用生态的支付体系和收入分成格局。卡根大法官拒绝苹果的紧急中止申请,使上诉法院藐视法庭认定维持有效,释放了最高法院对苹果反竞争行为的严厉信号。该案如果最终维持对全体开发者适用,将迫使苹果调整其30%的标准佣金率,可能引发类似"App Store税"松动的连锁反应——韩国、荷兰、日本等已在立法推动类似变革。从时间线看,案件已跨越近六年,其最终走向将定义移动应用市场"平台—开发者—用户"之间的权力基本盘。开发者社群普遍将此视为扭转与苹果关系的关键节点。',
      huaweiImpact: '苹果Epic案的最新司法进展为华为AppGallery在全球竞争格局中提供了战略性参照。直接利好:如果美国司法体系最终强制苹果降低佣金率或允许第三方支付,全球应用商店的"佣金天花板"将被打破,华为AppGallery可顺势推出更具竞争力的佣金方案(当前已采用相对灵活的费率),吸引受苹果低佣金化趋势驱动的开发者。合规路线图:美国最高法院对平台"守门人"角色的司法定性,与欧盟DMA和中国的平台经济监管在逻辑上趋同——全球主要经济体正在形成对应用商店平台权力的制衡共识。华为应将这一趋势纳入其全球化的合规框架设计中。战略机遇:Epic案暴露了苹果和Google在支付管控上的系统性弱点,华为AppGallery在拓展海外市场时,可以"开放、公平、低抽成"作为核心卖点,向开发者展示"拒绝垄断"的平台价值观。',
    },
