    summary: '5月20日市场研究机构数据显示,2026年Q1拉丁美洲智能手机出货3480万部,同比增长3%,而东南亚市场同比下降9%。三星以1290万部出货居首(份额37%),小米600万部第二,摩托罗拉490万部第三。荣耀出货340万部排名第四,同比大增30%领跑各品牌,市场份额升至10%。苹果出货180万部排名第五,同比增31%。',
