      huaweiImpact: '荣耀在拉美的30%高速增长验证了中国品牌在新兴市场的成功可行性。华为虽因制裁在拉美市场缺席,但可从荣耀的成功中提取可复用的经验。苹果31%的增长显示拉美高端市场潜力大。拉美国家如巴西对科技中立性偏好强,华为可善用隐私安全叙事来建立差异化品牌形象。',
